_BACKUP_SCRIPT = r'''
function enhanceProfileDesigner(){
  const form=document.getElementById('profile-editor');
  if(!form||form.dataset.designer==='true')return;
  form.dataset.designer='true';
  const first=form.querySelector('.profile-group'),advanced=form.querySelector('details'),toolbar=document.createElement('section');
  toolbar.className='profile-picker';
  toolbar.innerHTML=`<label>Add a setting<select id="profile-setting-select"><option value="">Choose a setting</option></select></label><div class="actions"><span id="profile-selected-count" class="badge">0 selected</span><button class="secondary" type="button" id="profile-add-setting">Add setting</button><button class="secondary" type="button" id="profile-baseline">Use baseline set</button></div>`;
  first.after(toolbar);
  const entries=[...form.querySelectorAll('.profile-entry')],selector=toolbar.querySelector('#profile-setting-select'),groups=new Map();
  for(const entry of entries){
    const control=entry.querySelector('[name]'),include=entry.querySelector('[data-profile-include]'),label=entry.dataset.label,fieldLabel=control.closest('label'),heading=document.createElement('div'),remove=document.createElement('button'),fieldset=entry.closest('.profile-group'),section=fieldset?.querySelector('legend')?.textContent||'Settings';
    entry.dataset.settingName=control.name;
    entry.classList.add('hidden');
    include.closest('label').classList.add('hidden');
    heading.className='profile-entry-heading';
    heading.innerHTML=`<strong>${esc(label)}</strong>`;
    remove.type='button';
    remove.className='badge profile-remove';
    remove.textContent='Remove';
    remove.setAttribute('aria-label',`Remove ${label}`);
    remove.onclick=()=>{include.checked=false;entry.classList.add('hidden');updateProfileDesigner()};
    heading.append(remove);
    for(const node of [...fieldLabel.childNodes])if(node.nodeType===3)node.remove();
    entry.prepend(heading);
    if(!groups.has(section)){
      const group=document.createElement('optgroup');
      group.label=advanced?.contains(entry)?`Advanced — ${section}`:section;
      groups.set(section,group);
      selector.append(group);
    }
    const option=document.createElement('option');
    option.value=control.name;
    option.textContent=label;
    groups.get(section).append(option);
  }
  function add(name){
    const entry=entries.find(item=>item.dataset.settingName===name);
    if(!entry)return;
    entry.querySelector('[data-profile-include]').checked=true;
    entry.classList.remove('hidden');
    updateProfileDesigner();
    if(advanced?.contains(entry))advanced.setAttribute('open','');
    entry.querySelector('[name]')?.focus();
  }
  function updateProfileDesigner(){
    const selected=entries.filter(item=>item.querySelector('[data-profile-include]').checked),count=selected.length;
    document.getElementById('profile-selected-count').textContent=`${count} selected`;
    for(const group of form.querySelectorAll('.profile-group')){
      if(group===first)continue;
      group.classList.toggle('hidden',![...group.querySelectorAll('.profile-entry')].some(item=>!item.classList.contains('hidden')));
    }
    const showAdvanced=advanced&&selected.some(item=>advanced.contains(item));
    advanced?.classList.toggle('hidden',!showAdvanced);
    if(advanced&&!showAdvanced)advanced.removeAttribute('open');
    for(const option of selector.options){
      if(option.value)option.disabled=selected.some(item=>item.dataset.settingName===option.value);
    }
  }
  window.updateProfileDesigner=updateProfileDesigner;
  toolbar.querySelector('#profile-add-setting').onclick=()=>{if(selector.value){add(selector.value);selector.value=''}};
  selector.addEventListener('change',()=>{if(selector.value){add(selector.value);selector.value=''}});
  toolbar.querySelector('#profile-baseline').onclick=()=>{['timezone_name','ntp_servers','loglevel','log_buffer_lines','ha_discovery','ha_discovery_prefix','mqtt_enabled','mqtt_port','mqtt_qos','syslog_enabled','syslog_port','syslog_transport','release_channel','release_check_schedule','release_check_time','release_auto_download','release_auto_activate','portal_transport','portal_port','portal_session_timeout_s','api_enabled','api_port','certificate_mode','certificate_method'].forEach(add)};
  updateProfileDesigner();
}
const backupState={items:[],settings:{},pending:null,renderSignature:''};
function renderBackupProgress(jobs=[]){const box=document.getElementById('backup-progress'),section=document.getElementById('backup-operations'),list=document.getElementById('backup-active-list');if(!box||!section||!list)return;if(!jobs.length){section.classList.add('hidden');box.innerHTML='';list.innerHTML='';return}const total=jobs.length,started=jobs.filter(job=>['running','complete'].includes(job.status)).length,complete=jobs.filter(job=>job.status==='complete').length,failed=jobs.some(job=>job.status==='failed');section.classList.remove('hidden');box.innerHTML=milestoneFlow(['Queued','Backing up','Stored'],[total,started,complete],total,failed);list.innerHTML=jobs.map(job=>{const device=state.devices.find(item=>item.id===job.target);return `<div class="operation-row"><span><strong>${esc(device?.name||job.target)}</strong><small>${esc(job.payload?.source||'manual')} encrypted backup</small></span>${statusBadge(job.status)}</div>`}).join('')}
function backupDeviceOptions(selected=''){return state.devices.filter(item=>item.enabled).map(item=>`<option value="${esc(item.id)}" ${item.id===selected?'selected':''}>${esc(item.name)} · ${esc(item.id)}</option>`).join('')}
function backupSize(value){if(value<1024)return value+' B';if(value<1048576)return (value/1024).toFixed(1)+' KiB';return (value/1048576).toFixed(1)+' MiB'}
function syncBackupTargetScope(){const scope=document.querySelector('[name="backup_target_scope"]:checked')?.value||'devices';document.getElementById('backup-device-targets')?.classList.toggle('hidden',scope!=='devices');document.getElementById('backup-cohort-targets')?.classList.toggle('hidden',scope!=='cohort')}
function renderBackupTargets(){const deviceBox=document.getElementById('backup-device-targets'),cohortBox=document.getElementById('backup-cohort-targets');if(!deviceBox||!cohortBox)return;const selected=new Set([...document.querySelectorAll('[name="backup_target_device"]:checked')].map(input=>input.value)),selectedCohorts=new Set([...document.querySelectorAll('[name="backup_target_cohort"]:checked')].map(input=>input.value));deviceBox.innerHTML=state.devices.filter(item=>item.enabled).map(device=>`<label class="check"><input type="checkbox" name="backup_target_device" value="${esc(device.id)}" ${selected.has(device.id)?'checked':''}><span>${esc(device.name)}<small>${esc(device.cohort)}</small></span></label>`).join('')||'<p class="muted">Register an enabled device first.</p>';const cohorts=[...new Set(state.devices.filter(item=>item.enabled).map(item=>item.cohort))];cohortBox.innerHTML=cohorts.map(cohort=>`<label class="check"><input type="checkbox" name="backup_target_cohort" value="${esc(cohort)}" ${selectedCohorts.has(cohort)?'checked':''}><span>${esc(cohort)}<small>${state.devices.filter(item=>item.enabled&&item.cohort===cohort).length} devices</small></span></label>`).join('');syncBackupTargetScope()}
function selectedBackupTargets(){const scope=document.querySelector('[name="backup_target_scope"]:checked')?.value||'devices',targets=[...document.querySelectorAll('[name="backup_target_device"]:checked')].map(input=>input.value),cohorts=[...document.querySelectorAll('[name="backup_target_cohort"]:checked')].map(input=>input.value);let devices;if(scope==='all')devices=state.devices.filter(item=>item.enabled);else if(scope==='cohort'){const chosen=new Set(cohorts);devices=state.devices.filter(item=>item.enabled&&chosen.has(item.cohort))}else{const chosen=new Set(targets);devices=state.devices.filter(item=>item.enabled&&chosen.has(item.id))}return{target_scope:scope,targets,cohorts,devices}}
function renderBackups(){const list=document.getElementById('backup-list');if(!list)return;const requested=Number(new URLSearchParams(location.search).get('backup')||0),html=backupState.items.map(item=>`<article id="backup-${item.id}" class="event"><time class="event-time">${esc(when(item.created_at))}</time><span class="event-dot"></span><div><div class="backup-title"><strong>${esc(item.device_name)} · complete configuration</strong><span class="badge good backup-encrypted">Encrypted</span></div><p>${esc(item.application_version||'Unknown app')} · ${esc(item.firmware_version||'Unknown core')} · ${esc(backupSize(item.size_bytes))} · ${esc(item.source)}</p><details data-disclosure-key="backup-restore-${item.id}"><summary>Preview or restore</summary><form class="backup-restore" data-backup-id="${item.id}"><div class="grid"><label>Target device<select name="target_device_id">${backupDeviceOptions(item.device_id)}</select></label><label class="check"><input name="credentials" type="checkbox" checked><span>Settings and secrets</span></label><label class="check"><input name="module_settings" type="checkbox" checked><span>Module configuration</span></label><label class="check"><input name="certificates_and_trust" type="checkbox" checked><span>Certificates, keys and trust</span></label></div><div class="backup-preview muted"></div><div class="actions"><button class="danger" type="button" onclick="deleteBackup(${item.id})">Delete</button><button class="secondary" type="button" onclick="previewBackup(this)">Preview restore</button><button class="backup-apply hidden" type="button" onclick="restoreBackup(this)">Restore configuration</button></div></form></details></div></article>`).join('')||'<p class="muted">No encrypted recovery points have been created.</p>';replacePreservingDetails(list,html);if(requested)requestAnimationFrame(()=>{const selected=document.getElementById(`backup-${requested}`);if(!selected)return;selected.querySelector('details').open=true;selected.scrollIntoView({block:'center'})})}
async function refreshBackups(force=false){if(!document.getElementById('backup-list'))return;const [data,devices]=await Promise.all([api('api/backups'),api('api/devices')]);state.devices=devices.devices;state.backups=data.backups||[];state.backupJobs=data.active_jobs||[];state.backupDeviceSettings=data.device_settings||{};backupState.items=data.backups;backupState.settings=data.settings;const signature=JSON.stringify([backupState.items.map(item=>[item.id,item.created_at,item.device_id,item.size_bytes]),state.devices.map(item=>[item.id,item.name,item.cohort,item.enabled])]);if(force||signature!==backupState.renderSignature){renderBackupTargets();renderBackups();backupState.renderSignature=signature}const button=document.querySelector('#backup-now button[type="submit"],#backup-now button:not([type])'),status=document.getElementById('backup-now-status'),completed=backupState.pending&&backupState.pending.targets.every(target=>backupState.items.some(item=>item.device_id===target&&Number(item.created_at)>=backupState.pending.startedAt-5));if(completed){backupState.pending=null;status.className='status success';status.textContent='Encrypted backups completed and added to backup history.'}if(!backupState.pending&&data.active_jobs?.length){backupState.pending={jobIds:data.active_jobs.map(job=>job.id),targets:[...new Set(data.active_jobs.map(job=>job.target))],startedAt:Math.min(...data.active_jobs.map(job=>Number(job.created_at)))};status.className='status';status.textContent=`${data.active_jobs.length} encrypted backup${data.active_jobs.length===1?' is':'s are'} still running…`}renderBackupProgress(data.active_jobs||[]);if(button)button.disabled=!!backupState.pending||!state.devices.some(item=>item.enabled)}
function restoreSections(form){return ['credentials','module_settings','certificates_and_trust'].filter(name=>form.elements[name].checked)}
function backupPreviewTable(preview){const rows=Array.isArray(preview.changes)?preview.changes:[],changed=rows.filter(row=>row.state!=='same').length,summary=`${changed} setting${changed===1?'':'s'} will change; ${rows.length} reviewed${preview.cross_device?' on a different target device':''}.`;if(!rows.length)return`<div class="status backup-preview-summary">${esc(summary)}</div>`;const body=rows.map(row=>{const state=row.state==='missing'?'Missing':row.state==='same'?'Unchanged':'Changed',tone=row.state==='missing'?'bad':row.state==='same'?'':'warn';return`<tr><td>${esc(row.path)}</td><td>${esc(row.before??'')}</td><td>${esc(row.after??'')}</td><td><span class="badge ${tone}">${state}</span></td></tr>`}).join('');return`<div class="status backup-preview-summary">${esc(summary)} Review the values below, then use Restore configuration if they are correct.</div><div class="backup-diff"><table><thead><tr><th>Setting</th><th>Current configuration</th><th>Backup configuration</th><th>Result</th></tr></thead><tbody>${body}</tbody></table></div>`}
async function previewBackup(button){const form=button.closest('form'),box=form.querySelector('.backup-preview'),target=form.elements.target_device_id.value;button.disabled=true;try{const preview=await api(`api/backups/${form.dataset.backupId}/preview`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target_device_id:target,sections:restoreSections(form)})});box.className='backup-preview';box.innerHTML=backupPreviewTable(preview);form.querySelector('.backup-apply').classList.remove('hidden')}catch(error){box.className='backup-preview status error';box.textContent=error.message}finally{button.disabled=false}}
async function restoreBackup(button){const form=button.closest('form'),target=form.elements.target_device_id.value,confirmation=prompt(`This replaces the selected protected configuration and requires a restart. Type "restore ${target}" to continue.`);if(confirmation===null)return;button.disabled=true;try{await api(`api/backups/${form.dataset.backupId}/restore`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target_device_id:target,sections:restoreSections(form),confirmation})});form.querySelector('.backup-preview').className='backup-preview status success';form.querySelector('.backup-preview').textContent='Configuration restored and restart marked as required.'}catch(error){form.querySelector('.backup-preview').className='backup-preview status error';form.querySelector('.backup-preview').textContent=error.message}finally{button.disabled=false}}
async function deleteBackup(id){if(!confirm('Delete this encrypted recovery point?'))return;await api('api/backups/'+id,{method:'DELETE'});await refreshBackups()}
function backupError(detail){const value=String(detail||'');return value.includes('configuration:write')||value.toLowerCase().includes('api-write')?'The Management API client needs the configuration:write scope on this device. Management will retry automatically after the scope is added.':value}
async function waitForBackupJobs(identifiers,status){const deadline=Date.now()+120000;while(Date.now()<deadline){const jobs=await Promise.all(identifiers.map(identifier=>api('api/jobs/'+identifier).then(data=>data.job))),complete=jobs.filter(job=>job.status==='complete').length,failed=jobs.find(job=>job.status==='failed');renderBackupProgress(jobs);if(complete===jobs.length){await refreshBackups(true);renderBackupProgress(jobs);backupState.pending=null;status.className='status success';status.textContent=`${complete} encrypted backup${complete===1?'':'s'} completed and added to recovery points.`;return}if(failed){await refreshBackups();renderBackupProgress(jobs);if(!backupState.pending)return;throw new Error(backupError(failed.last_error)||'Encrypted backup failed.')}const retry=jobs.find(job=>job.last_error);if(retry){status.className='status';status.textContent=`${backupError(retry.last_error)} Retrying automatically; no new backup request is required.`}else{status.className='status';status.textContent=`Creating encrypted backups… ${complete} of ${jobs.length} complete.`}await new Promise(resolve=>setTimeout(resolve,2000))}status.className='status';status.textContent='Backups are still running in the background. Recovery points will update automatically when they complete.'}
function syncActionMode(updateUrl=false){const actionRoot=document.querySelector('[data-page-section="actions"]'),backupRoot=document.getElementById('backup-action-content');if(!actionRoot||!backupRoot)return;const params=new URLSearchParams(location.search),legacy=location.pathname.endsWith('/backups')?'backup':'deploy',requested=params.get('mode')||legacy,mode=['deploy','backup','restore'].includes(requested)?requested:'deploy',selected=document.querySelector(`[name="action_mode"][value="${mode}"]`);if(selected)selected.checked=true;for(const element of actionRoot.querySelectorAll(':scope>form,:scope>section.panel'))element.classList.toggle('mode-hidden',mode!=='deploy');backupRoot.classList.toggle('hidden',mode==='deploy');document.getElementById('backup-create')?.classList.toggle('mode-hidden',mode!=='backup');document.getElementById('backup-operations')?.classList.toggle('mode-hidden',mode!=='backup');document.getElementById('backup-history')?.classList.toggle('mode-hidden',mode!=='restore');if(updateUrl){const query=new URLSearchParams(location.search);query.set('mode',mode);query.delete('backup');history.replaceState({},'',`actions?${query.toString()}`)}}
document.querySelectorAll('[name="backup_target_scope"]').forEach(input=>input.addEventListener('change',syncBackupTargetScope));
document.querySelectorAll('[name="action_mode"]').forEach(input=>input.addEventListener('change',()=>syncActionMode(true)));
document.getElementById('backup-now')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,status=document.getElementById('backup-now-status'),button=form.querySelector('button[type="submit"],button:not([type])'),selection=selectedBackupTargets(),startedAt=Math.floor(Date.now()/1000);if(!selection.devices.length){status.className='status error';status.textContent='Choose at least one available backup target.';return}button.disabled=true;try{const result=await api('api/backups',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target_scope:selection.target_scope,targets:selection.targets,cohorts:selection.cohorts})}),jobs=result.jobs||[];backupState.pending={jobIds:jobs.map(job=>job.id),targets:selection.devices.map(item=>item.id),startedAt};await waitForBackupJobs(backupState.pending.jobIds,status)}catch(error){status.className='status error';status.textContent=error.message;backupState.pending=null}finally{button.disabled=!!backupState.pending}});
'''
